  rw_cells usegs m RCTX (ctx_head_cells st) ->
  rw_cells usegs m RMLOCK [C4 (wz 0)] ->
  rw_cells usegs m (bv_unsigned sp + -48) [C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav] ->
